"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[42979],{21935:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>h,default:()=>u,frontMatter:()=>s,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"zen/09","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/zen/09.md","sourceDirName":"zen","slug":"/zen/09","permalink":"/en/zen/09","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"09","title":"","hide_table_of_contents":true},"sidebar":"zenSidebar","previous":{"title":"\u7f20\u4e2d\u8bf4\u7985\uff1a\u7f20\u975e\u7f20\u3001\u7985\u975e\u7985\uff0c\u67af\u6728\u9f99\u541f\u7167\u5927\u5343\uff08\u516b\uff09 (2006/2/2 14:26:04)","permalink":"/en/zen/08"},"next":{"title":"\u7f20\u4e2d\u8bf4\u7985\uff1a\u7f20\u975e\u7f20\u3001\u7985\u975e\u7985\uff0c\u67af\u6728\u9f99\u541f\u7167\u5927\u5343\u3002\uff08\u5341\uff09 (2006/2/2 20:25:56)","permalink":"/en/zen/10"}}');var a=n(74848),o=n(28453),r=n(67787);const s={id:"09",title:"",hide_table_of_contents:!0},h=void 0,l={},d=[...r.RM];function c(e){return(0,a.jsx)(r.Ay,{})}function u(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(c,{...e})}):c()}},28453:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>s});var i=n(96540);const a={},o=i.createContext(a);function r(e){const t=i.useContext(o);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),i.createElement(o.Provider,{value:t},e.children)}},67787:(e,t,n)=>{n.d(t,{Ay:()=>s,RM:()=>o});var i=n(74848),a=n(28453);const o=[];function r(e){const t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"ch\xe1n-zh\u014dng-shu\u014d-ch\xe1n-entanglement-is-not-entanglement-zen-is-not-zen--a-dead-trees-dragon-song-illuminates-the-great-thousand-worlds-ix",children:"Ch\xe1n Zh\u014dng Shu\u014d Ch\xe1n: Entanglement Is Not Entanglement, Zen Is Not Zen \u2014 A Dead Tree's Dragon Song Illuminates the Great Thousand Worlds (IX)"})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"2006/2/2 18:53:05"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"Freedom is entanglement. Those in this world who vainly seek liberation by trying to escape entanglement do so through no more than four paths: First, seeking in matter external to the mind. Second, seeking in mind external to matter. Third, groping about where mind and matter are one suchness. Fourth, exploring between neither-mind-nor-matter. Beyond these four, there is no other path. All four are delusory conceptual fixations \u2014 mere idle theorizing."}),"\n",(0,i.jsx)(t.p,{children:'Those who seek in matter external to the mind use mind to reflect matter, making mind a function of matter. The so-called "investigating things to extend knowledge" \u2014 exhausting the principles of matter through practice, so that the mind is liberated. This necessarily presupposes that the principle of matter exists and that the mind can apprehend matter. The so-called "principle of matter" is in truth delusory conceptual fixation. There is this matter, therefore there is this matter\'s principle. The so-called principles of the universe that we can know exist only because we first exist in this particular universe. The development of relativity and quantum mechanics has already proven that the so-called principle of matter, divorced from an observer, is meaningless. The universe in which we find ourselves is actually the manifestation of our collective karma \u2014 how could this be the only universe! Those who seek in matter external to the mind are in truth seeking within the collective karma that we share, mutually entangled and continuing \u2014 a phantom play.'}),"\n",(0,i.jsx)(t.p,{children:"Those who seek in mind external to matter fantasize that the mind can be liberated apart from matter. But apart from matter, how can the mind exist? Some say that what cannot be separated from matter is the deluded mind, and that there is an ever-abiding true mind \u2014 without going, without coming, originally liberated, capable of being the master of all things. Truly the ravings of a feverish mind. These people aspire to eliminate the false and preserve the true, yet they do not know the truth of the false's falseness, the falsity of the truth's truth. Seeking truth is actually falsity; eliminating falsity leaves no truth. Our minds are aggregates of material phenomena \u2014 this mind originally has nowhere to rest. Mutually entangled and continuing \u2014 a phantom play."}),"\n",(0,i.jsx)(t.p,{children:'Those who grope about where mind and matter are one suchness speculate that the so-called monism of mind-matter is the true source of the universe \u2014 outside mind there is no matter, outside matter there is no mind. Exhaust the mind and you exhaust principle; exhaust principle and you comprehend the mind. Return to the source, and one liberation liberates all, one completion completes all. This type of discourse is extremely popular, and most of those today who call themselves practitioners of Zen talk this way. But the myriad dharmas return to the One, and the One is still the root of birth and death. The so-called "returning to the source" \u2014 there is originally no origin, the source is not a source. That which can serve as origin and source is neither origin nor source. Mutually entangled and continuing \u2014 a phantom play.'}),"\n",(0,i.jsx)(t.p,{children:"Those who explore between neither-mind-nor-matter establish a source that is neither mind nor matter, and seek liberation by taking refuge in it. Some call it God, some call it a deity, some call it the True Lord, some call it Truth, some call it Liberation, some call it the Sovereign, some call it Brahman, some call it the Great Dao, some call it True Emptiness \u2014 and so on, too many to enumerate. These people are simply engaging in deluded wishful thinking, falsely negating mind and matter to establish something that is neither mind nor matter, not knowing that not-mind is mind and not-matter is matter. Not-establishing yet establishing everywhere. Mutually entangled and continuing \u2014 a phantom play."}),"\n",(0,i.jsx)(t.p,{children:'The so-called "beyond these four, there is no other path" \u2014 this is Zen, free from the above four kinds of idle theorizing. Zen is not a path. "No other" is not none, and "none other" is not no-other.'}),"\n",(0,i.jsx)(t.p,{children:"A verse:"}),"\n",(0,i.jsxs)(t.p,{children:["Entering the worldly city drunk, through how many siege walls,",(0,i.jsx)("br",{}),"\nIn an instant, joys and sorrows dissolve into poured wine.",(0,i.jsx)("br",{}),"\nThe years sing back \u2014 the heart grows vast and great,",(0,i.jsx)("br",{}),"\nHeaven and earth shift like shadows \u2014 the eyes become clear and bright.",(0,i.jsx)("br",{}),"\nAll conditions, all self, all the same affliction,",(0,i.jsx)("br",{}),"\nNeither false nor true, neither the second name.",(0,i.jsx)("br",{}),"\nHiding at the East Sea, mountains galloping like horses,",(0,i.jsx)("br",{}),"\nOn Tiantai's Huading Peak \u2014 what is going on?"]})]})}function s(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(r,{...e})}):r(e)}}}]);